function Upgrades:ScanBatch()
    local job, generation = self.job, self.generation
    if not job or not self:IsEnabledForCharacter() then return end
    -- Eight slots per slice bounds scoring work and lets bag/equipment events cancel stale scans.
    for _ = 1, 8 do
        local count = Container("GetContainerNumSlots", job.bag)
        if not Number(count) or count < 0 then
            self.job = nil
            return
        end
        job.slot = job.slot + 1
        while job.slot > count do
            job.bag, job.slot = job.bag + 1, 1
            if job.bag > (NUM_BAG_SLOTS or 4) then
                self:FinishScan(job)
                return
            end
            count = Container("GetContainerNumSlots", job.bag)
            if not Number(count) or count < 0 then
                self.job = nil
                return
            end
        end
        local link = Container("GetContainerItemLink", job.bag, job.slot)
        if Public(link) and type(link) == "string" then
            local gain, ready, plan, comparison = APR.RewardScoring:GetUpgrade(link, job.scale)
            local refusal = self:RefusalIdentity(job.scoringIdentity, comparison)
            if not ready then
                local id = tonumber(link:match("item:(%d+)"))
                if id then job.pending[id] = true end
            elseif Number(gain) and gain > 0 and plan and plan.executable ~= false
                and (not refusal or self.dismissed[link] ~= refusal) then
                job.candidates[#job.candidates + 1] = {
                    link = link,
                    gain = gain,
                    plan = plan,
                    bag = job.bag,
                    slot = job.slot,
                    signature = job.signature,
                    scoringIdentity = job.scoringIdentity,
                    refusalIdentity = refusal,
                }
            end
        end
    end
    self.timer = C_Timer.NewTimer(
        0, --[[APR_DIAG]]
        APRTrace("APR-Core/features/player/BagUpgrades.lua:121:callback#15", --[[/APR_DIAG]] function()
            self.timer = nil
            if self.generation == generation and self.job == job then self:ScanBatch() end
        end--[[APR_DIAG]]) --[[/APR_DIAG]]
    )
end--[[APR_DIAG]]
Upgrades.ScanBatch = APRTrace("APR-Core/features/player/BagUpgrades.lua:95:Upgrades:ScanBatch#14", Upgrades.ScanBatch)--[[/APR_DIAG]]

-- Profile names and scorer identities survive reload; table/closure addresses do not.
function Upgrades:RefusalIdentity(scoringIdentity, comparison)
    if type(comparison) ~= "string" then return end
    local database = APR.settings and APR.settings.db
    local profile = database and database.GetCurrentProfile and database:GetCurrentProfile() or ""
    return string.format("%q:%q:%q", profile, scoringIdentity, comparison)
end--[[APR_DIAG]]
Upgrades.RefusalIdentity = APRTrace("APR-Core/features/player/BagUpgrades.lua:193:Upgrades:RefusalIdentity#27", Upgrades.RefusalIdentity)--[[/APR_DIAG]]

function Upgrades:FinishScan(job)
    local generation = self.generation
    self.job = nil
    local scale, identity = self:GetScale()
    if not scale or identity ~= job.scoringIdentity or EquipmentSignature() ~= job.signature then
        self:QueueScan()
        return
    end
    -- Request each missing item at most twice between inventory/scoring changes.
    -- Some unusable/opaque items never produce a score; they must not loop forever
    -- or prevent independently loaded upgrades from being offered.
    if next(job.pending) then
        for id in job.signature:gmatch("item:(%d+)") do
            job.pending[tonumber(id)] = true
        end
        self.requests = self.requests or {}
        local pending = {}
        for id in pairs(job.pending) do
            if (self.requests[id] or 0) < 2 then
                self.requests[id] = (self.requests[id] or 0) + 1
                pending[id] = true
            end
        end
        self.pendingIDs = pending
        self:RegisterEvent("ITEM_DATA_LOAD_RESULT", "OnItemData")
        for id in pairs(pending) do
            if C_Item and C_Item.RequestLoadItemDataByID then C_Item.RequestLoadItemDataByID(id) end
        end
        if self.generation ~= generation then return end
        if next(pending) then
            -- A failed/missing item event also has a bounded recovery path.
            local tmpGeneration = self.generation
            self.timer = C_Timer.NewTimer(
                1, --[[APR_DIAG]]
                APRTrace("APR-Core/features/player/BagUpgrades.lua:150:callback#17", --[[/APR_DIAG]] function()
                    self.timer = nil
                    if self.generation == tmpGeneration then self:QueueScan() end
                end--[[APR_DIAG]]) --[[/APR_DIAG]]
            )
            return
        end
        self:UnregisterEvent("ITEM_DATA_LOAD_RESULT")
        self.pendingIDs = nil
    end
    table.sort(
        job.candidates, --[[APR_DIAG]]
        APRTrace("APR-Core/features/player/BagUpgrades.lua:159:callback#18", --[[/APR_DIAG]] function(a, b)
            if a.gain ~= b.gain then return a.gain > b.gain end
            if a.bag ~= b.bag then return a.bag < b.bag end
            return a.slot < b.slot
        end--[[APR_DIAG]]) --[[/APR_DIAG]]
    )
    if job.candidates[1] then self:Offer(job.candidates[1]) end
end--[[APR_DIAG]]
Upgrades.FinishScan =
    APRTrace("APR-Core/features/player/BagUpgrades.lua:127:Upgrades:FinishScan#16", Upgrades.FinishScan)--[[/APR_DIAG]]

