    self.dialog = APR.UI:ShowConfirmationDialog({
        dialogName = "APRBagUpgradePopup",
        title = L["GEAR_UPGRADE_TITLE"],
        description = L["GEAR_UPGRADE_PROMPT"] .. (text ~= "" and "\n" .. text or ""),
        comparison = rows,
        acceptText = EQUIP_ITEM or EQUIP or ACCEPT,
        cancelText = IGNORE or CANCEL,
    }, onAccept, onCancel)
    if not self.dialog or not self.dialog:IsShown() then
        self.prompt, self.waiting = nil, true
    end
end--[[APR_DIAG]]
Upgrades.Offer = APRTrace("APR-Core/features/player/BagUpgrades.lua:189:Upgrades:Offer#20", Upgrades.Offer)--[[/APR_DIAG]]

function Upgrades:RefreshSettings()
    self:CancelScan()
    self:CancelPrompt()
    self:UnregisterAllEvents()
    if not self:IsEnabledForCharacter() then return end
    for _, event in ipairs(EVENTS) do
        self:RegisterEvent(event, "QueueScan")
    end
    self:QueueScan()
end--[[APR_DIAG]]
Upgrades.RefreshSettings =
    APRTrace("APR-Core/features/player/BagUpgrades.lua:219:Upgrades:RefreshSettings#23", Upgrades.RefreshSettings)--[[/APR_DIAG]]

function Upgrades:OnEnable()
    self.active = true
    if hooksecurefunc and StaticPopup_OnHide and not self.popupHooked then
        self.popupHooked = true
        hooksecurefunc(
            "StaticPopup_OnHide", --[[APR_DIAG]]
            APRTrace("APR-Core/features/player/BagUpgrades.lua:232:callback#25", --[[/APR_DIAG]] function()
                if self.waiting and self:IsEnabledForCharacter() then
                    self.waiting = nil
                    self:QueueScan()
                end
            end--[[APR_DIAG]]) --[[/APR_DIAG]]
        )
    end
    self:RefreshSettings()
end--[[APR_DIAG]]
Upgrades.OnEnable = APRTrace("APR-Core/features/player/BagUpgrades.lua:228:Upgrades:OnEnable#24", Upgrades.OnEnable)--[[/APR_DIAG]]

function Upgrades:OnDisable()
    self.active = false
    self:RefreshSettings()
end--[[APR_DIAG]]
